package techguns.gametest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.gametest.*;
import techguns.*;
import techguns.blocks.MiningChargeBlock;
import techguns.tileentities.MiningChargeEntity;
@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class MiningChargeGameTests {
    private static MiningChargeEntity charge(GameTestHelper h,boolean advanced,Direction direction){h.setBlock(2,1,2,(advanced?TGCharges.ADVANCED:TGCharges.TNT).get().defaultBlockState().setValue(MiningChargeBlock.FACING,direction));return (MiningChargeEntity)h.getBlockEntity(new BlockPos(2,1,2));}
    @GameTest(template="empty") public static void chargeControlsUseSourceBoundsAndFreezeWhenArmed(GameTestHelper h){var player=h.makeMockPlayer();var charge=charge(h,true,Direction.DOWN);for(int i=0;i<30;i++){charge.button(player,1);charge.button(player,3);charge.button(player,5);}h.assertTrue(charge.diameter==7&&charge.length==10&&charge.fuse==200,"Advanced source maxima are seven across, ten deep and ten seconds");for(int i=0;i<30;i++){charge.button(player,2);charge.button(player,4);charge.button(player,6);}h.assertTrue(charge.diameter==3&&charge.length==2&&charge.fuse==60,"Source minimum settings remain enforced");charge.button(player,0);h.assertFalse(charge.button(player,5),"Armed settings cannot be edited by a delayed GUI packet");h.assertTrue(charge.getBlockState().getValue(MiningChargeBlock.ARMED),"Arming swaps to the source armed model");var saved=charge.saveWithoutMetadata();var loaded=new MiningChargeEntity(charge.getBlockPos(),charge.getBlockState());loaded.load(saved);h.assertTrue(loaded.armed&&loaded.fuse==60&&loaded.length==2&&loaded.diameter==3,"Armed countdown and shape survive saving");h.succeed();}
    @GameTest(template="empty") public static void chargeVolumesAndHardnessRetainSourceRules(GameTestHelper h){for(Direction direction:Direction.values()){var charge=charge(h,true,direction);h.assertTrue(charge.slice().size()==25,"Advanced default width five makes twenty-five parallel lines in every orientation");charge.diameter=7;h.assertTrue(charge.slice().size()==49,"Maximum width seven makes forty-nine parallel lines");h.getLevel().removeBlock(charge.getBlockPos(),false);}var ordinary=charge(h,false,Direction.DOWN);h.assertFalse(ordinary.breakable(-1),"Bedrock cannot be mined");h.assertFalse(ordinary.breakable(TGConfig.explosiveChargeMaxBlockHardness),"Ordinary source hardness bound is strict");h.getLevel().removeBlock(ordinary.getBlockPos(),false);var advanced=charge(h,true,Direction.DOWN);h.assertTrue(advanced.breakable(TGConfig.explosiveChargeAdvancedMaxBlockHardness),"Advanced source hardness bound is inclusive");h.succeed();}
    @GameTest(template="empty") public static void miningChargeStopsEachLineAtBedrockAndNeverDamagesEntities(GameTestHelper h){var charge=charge(h,false,Direction.DOWN);var owner=h.makeMockSurvivalPlayer();charge.access.place(owner);h.getLevel().setBlockAndUpdate(charge.getBlockPos().below(),Blocks.BEDROCK.defaultBlockState());h.getLevel().setBlockAndUpdate(charge.getBlockPos().below(2),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(charge.getBlockPos().east().below(),Blocks.STONE.defaultBlockState());charge.length=2;var protectedPos=charge.getBlockPos().below(2);var minedPos=charge.getBlockPos().east().below();float health=owner.getHealth();for(var origin:charge.slice())charge.mineLine(owner,origin,Direction.DOWN);h.assertTrue(h.getLevel().getBlockState(protectedPos).is(Blocks.STONE),"Unbreakable block stops its own ray before the block behind it");h.assertTrue(h.getLevel().getBlockState(minedPos).isAir(),"Adjacent ray can still mine its own column");h.assertTrue(owner.getHealth()==health,"Source mining charges destroy blocks without generic TNT entity damage");h.succeed();}
}
